// =======================================================================
// NODO CODE: RECORTE Y NORMALIZACIÓN DE SEMIS + CISTERNADO (MOVIMIENTOS)
// =======================================================================
const rows = $input.all();
const semisMap = new Map();
let currentServicio = 'GENERAL';

// Palabras reservadas a descartar como patentes
const blacklist = new Set([
  'TRACTOR', 'PATENTE', 'SEMI', 'CISTERNADO', 'NOVEDADES', 
  'LIVIANO', 'METANOL', 'CAMPO', 'GLP', 'SOCIO', 'SEPTIEMBRE', 'OCTUBRE', 'FECHA', 'N'
]);

for (const item of rows) {
  const row = item.json;

  // Soporta tanto propiedades por nombre de columna como índices por posición
  const colA = String(row['N'] || row['0'] || Object.values(row)[0] || '').trim();
  const colC = String(row['N° UTE'] || row['2'] || Object.values(row)[2] || '').trim();
  const colD = String(row['Cisternado'] || row['3'] || Object.values(row)[3] || '').trim();
  const colE = String(row['Tractor'] || row['4'] || Object.values(row)[4] || '').trim();
  const colF = String(row['SEMI'] || row['5'] || Object.values(row)[5] || '').trim();

  // 1. Detección de fila cabecera de Servicio / Categoría (Col A con texto y demás columnas vacías)
  if (colA && !colC && !colE && !colF) {
    const upA = colA.toUpperCase();
    if (!upA.includes('FECHA') && !upA.includes('N°') && !upA.includes('OCTUBRE') && !upA.includes('NOVEDADES')) {
      currentServicio = upA;
    }
    continue;
  }

  // 2. Extracción y saneamiento de patente del SEMI (sin espacios, mayúsculas)
  const rawSemi = colF.toUpperCase().replace(/\s+/g, '');
  if (!rawSemi || blacklist.has(rawSemi) || rawSemi.length < 5) {
    continue;
  }

  // 3. Saneamiento del cisternado (ej. '7-7-5-5-6-7')
  const cisternadoLimpio = colD && colD !== '-' ? colD.trim() : null;

  // 4. Deduplicación canónica (sin íconos de estado, estado estándar 'disponible')
  if (!semisMap.has(rawSemi)) {
    semisMap.set(rawSemi, {
      patente: rawSemi,
      cisternado: cisternadoLimpio,
      servicio_denominacion: currentServicio,
      estado: 'disponible',
      n_ute: colC || null,
      actualizado_el: new Date().toISOString()
    });
  } else {
    // Si ya existía sin cisternado pero en otra fila lo tiene, actualizar
    const existing = semisMap.get(rawSemi);
    if (!existing.cisternado && cisternadoLimpio) {
      existing.cisternado = cisternadoLimpio;
    }
  }
}

return Array.from(semisMap.values()).map(s => ({ json: s }));

const items = $input.all();
const total = items.length;
const conCisternado = items.filter(i => i.json.cisternado).length;
const sample = items.slice(0, 5).map(i => `${i.json.patente || i.json} (${i.json.cisternado || 'S/C'})`);

return [{
  json: {
    timestamp: new Date().toLocaleString('es-AR'),
    modulo: 'Bases Organización - Semis y Cisternado',
    total_semis_sincronizados: total,
    con_cisternado: conCisternado,
    sin_cisternado: total - conCisternado,
    estado: '✅ Catálogo de semis y cisternados actualizado con éxito en Supabase',
    muestra_semis: sample,
    detalle: 'Patentes normalizadas, cisternados asignados y marcas preservadas en base de datos.'
  }
}];
